ALTER TABLE machines ADD COLUMN verifiers TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(verifiers));
CREATE TABLE runner_jobs(id TEXT PRIMARY KEY, projectId TEXT NOT NULL REFERENCES projects(id), workId TEXT NOT NULL REFERENCES work_items(id), workspaceId TEXT NOT NULL REFERENCES workspaces(id), machineId TEXT NOT NULL REFERENCES machines(id), kind TEXT NOT NULL CHECK(kind IN ('diff','verify')), state TEXT NOT NULL CHECK(state IN ('queued','running','succeeded','failed','indeterminate')), payload TEXT NOT NULL CHECK(json_valid(payload)), result TEXT CHECK(result IS NULL OR json_valid(result)), requestedBy TEXT NOT NULL REFERENCES identities(id), expectedHead TEXT NOT NULL, expectedVersion INTEGER NOT NULL, createdAt INTEGER NOT NULL, startedAt INTEGER, finishedAt INTEGER);
CREATE INDEX runner_jobs_pending ON runner_jobs(machineId,state,createdAt);
